async function eventWithAvailability(id) {
  const key = `event:${id}:availability`;
  const hit = await cache.get(key);
  if (hit) return hit;
  const fresh = await buildAvailability(id);
  await cache.set(key, fresh, { ttl: 15 }); // seconds
  return fresh;
}

async function withTimeout<T>(work: Promise<T>, ms: number, fallback: T) {
  let timer: NodeJS.Timeout;
  const timeout = new Promise<T>((resolve) => {
    timer = setTimeout(() => resolve(fallback), ms);
  });
  try {
    return await Promise.race([work, timeout]);
  } finally {
    clearTimeout(timer!);
  }
}

